"""Sony · Scala Shopping Cumbayá — 15 s spot: music + SFX, generated by code.

Writes (48 kHz, stereo, 16-bit WAV):
  public/audio/sony-scala-mix.wav   master: -14 LUFS integrated, <= -1.2 dBTP
  public/audio/music.wav            music stem (same master gain curve)
  public/audio/sfx.wav              SFX stem   (same master gain curve)
  audio-src/loudness-report.md      momentary LUFS per event + master figures

Nothing is sampled or downloaded: every sound is synthesised below.
Timing comes from src/timeline/cues.json (the same file the video uses), so
each effect lands on its frame. 30 fps -> 1 frame = 1600 samples.

Music: 120 BPM in D major, re-harmonised per bar
  Bm9 | Gmaj7 | D/F# | Em9 (breakdown) | Gmaj7 (drop @ f240) | A | Asus4 ->
  Dmaj9 hit at 13.0 s (f390) with a clean reverb tail.

Usage: python3 -I audio-src/compose.py <project_dir>
"""
import json
import sys
from pathlib import Path

import numpy as np
from scipy import signal
from scipy.io import wavfile
from scipy.ndimage import maximum_filter1d, minimum_filter1d

SR = 48000
FPS = 30
SPF = SR // FPS  # samples per frame = 1600
DUR_FRAMES = 450
N = DUR_FRAMES * SPF  # 720000 samples = 15.000 s
BPM = 120
BEAT = 60.0 / BPM  # 0.5 s
BAR = 4 * BEAT  # 2.0 s
TARGET_LUFS = -14.0
CEILING_DBTP = -1.2
RNG = np.random.default_rng(20261031)


def fs(frame: float) -> int:
    """frame -> sample index"""
    return int(round(frame * SPF))


def tsec(frame: float) -> float:
    return frame / FPS


def mtof(m: float) -> float:
    return 440.0 * 2.0 ** ((m - 69) / 12.0)


def db(x: float) -> float:
    return 20 * np.log10(max(x, 1e-12))


# --------------------------------------------------------------------------
# BS.1770-4 loudness (K-weighting, 400 ms blocks, absolute + relative gates)
# --------------------------------------------------------------------------
K_SHELF = (np.array([1.53512485958697, -2.69169618940638, 1.19839281085285]),
           np.array([1.0, -1.69065929318241, 0.73248077421585]))
K_HP = (np.array([1.0, -2.0, 1.0]), np.array([1.0, -1.99004745483398, 0.99007225036621]))


def k_weight(x: np.ndarray) -> np.ndarray:
    y = signal.lfilter(*K_SHELF, x, axis=0)
    return signal.lfilter(*K_HP, y, axis=0)


def _block_power(x: np.ndarray, win: float = 0.4, hop: float = 0.1) -> np.ndarray:
    z = k_weight(x) ** 2  # (n, ch)
    w, h = int(win * SR), int(hop * SR)
    c = np.cumsum(np.vstack([np.zeros((1, z.shape[1])), z]), axis=0)
    starts = np.arange(0, len(z) - w + 1, h)
    ms = (c[starts + w] - c[starts]) / w  # mean square per channel
    return ms.sum(axis=1)  # channel weights G = 1 for L/R


def integrated_lufs(x: np.ndarray) -> float:
    p = _block_power(x)
    lk = -0.691 + 10 * np.log10(np.maximum(p, 1e-20))
    p = p[lk > -70.0]
    if len(p) == 0:
        return -np.inf
    rel = -0.691 + 10 * np.log10(p.mean()) - 10.0
    lk = -0.691 + 10 * np.log10(p)
    p = p[lk > rel]
    return float(-0.691 + 10 * np.log10(p.mean()))


def momentary_lufs(x: np.ndarray, start: int) -> float:
    seg = x[start:start + int(0.4 * SR)]
    if len(seg) < int(0.4 * SR):
        seg = np.vstack([seg, np.zeros((int(0.4 * SR) - len(seg), x.shape[1]))])
    z = k_weight(seg) ** 2
    return float(-0.691 + 10 * np.log10(max(z.mean(axis=0).sum(), 1e-20)))


def true_peak_dbtp(x: np.ndarray) -> float:
    up = signal.resample_poly(x, 4, 1, axis=0)
    return db(np.max(np.abs(up)))


# --------------------------------------------------------------------------
# DSP primitives
# --------------------------------------------------------------------------
def pan_gains(p: np.ndarray | float):
    th = (np.asarray(p) + 1.0) * np.pi / 4.0
    return np.cos(th), np.sin(th)


def place(bus: np.ndarray, mono: np.ndarray, start: int, pan=0.0, gain=1.0) -> None:
    """Add a mono signal to a stereo bus with constant-power pan (scalar or per-sample)."""
    if start >= len(bus):
        return
    if start < 0:
        mono = mono[-start:]
        if isinstance(pan, np.ndarray):
            pan = pan[-start:]
        start = 0
    n = min(len(mono), len(bus) - start)
    if n <= 0:
        return
    if isinstance(pan, np.ndarray) and len(pan) < n:
        pan = np.concatenate([pan, np.full(n - len(pan), pan[-1])])
    l, r = pan_gains(pan if not isinstance(pan, np.ndarray) else pan[:n])
    bus[start:start + n, 0] += mono[:n] * l * gain
    bus[start:start + n, 1] += mono[:n] * r * gain


def place_st(bus: np.ndarray, st: np.ndarray, start: int, gain=1.0) -> None:
    if start < 0:
        st = st[-start:]
        start = 0
    n = min(len(st), len(bus) - start)
    if n > 0:
        bus[start:start + n] += st[:n] * gain


def polyblep_saw(freq: np.ndarray, phase0: float = 0.0) -> np.ndarray:
    dt = freq / SR
    ph = (phase0 + np.cumsum(dt)) % 1.0
    y = 2.0 * ph - 1.0
    a = ph < dt
    t = ph[a] / dt[a]
    y[a] -= t + t - t * t - 1.0
    b = ph > 1.0 - dt
    t = (ph[b] - 1.0) / dt[b]
    y[b] -= t * t + t + t + 1.0
    return y


def sine_sweep(f: np.ndarray, phase0: float = 0.0) -> np.ndarray:
    return np.sin(phase0 + 2 * np.pi * np.cumsum(f) / SR)


def env_exp(n: int, attack: float, tau: float) -> np.ndarray:
    t = np.arange(n) / SR
    a = np.clip(t / max(attack, 1e-6), 0, 1)
    return a * np.exp(-np.maximum(t - attack, 0) / tau)


def butter(kind: str, f, order: int = 2):
    return signal.butter(order, f, btype=kind, fs=SR, output="sos")


def filt(x: np.ndarray, sos) -> np.ndarray:
    return signal.sosfilt(sos, x, axis=0)


def tv_lowpass(x: np.ndarray, cutoff: np.ndarray, block: int = 256) -> np.ndarray:
    """Time-varying 2nd-order low-pass (block-wise coefficient updates)."""
    y = np.zeros_like(x)
    zi = None
    for s in range(0, len(x), block):
        fc = float(np.clip(cutoff[min(s + block // 2, len(cutoff) - 1)], 30, SR * 0.45))
        sos = butter("lowpass", fc)
        if zi is None:
            zi = np.zeros((sos.shape[0], 2) + x.shape[1:])
        y[s:s + block], zi = signal.sosfilt(sos, x[s:s + block], axis=0, zi=zi)
    return y


def reverb_ir(seconds: float, tau: float, bright: float = 6000.0, predelay: float = 0.012) -> np.ndarray:
    n = int(seconds * SR)
    t = np.arange(n) / SR
    ir = RNG.standard_normal((n, 2)) * np.exp(-t / tau)[:, None]
    ir = filt(ir, butter("lowpass", bright))
    ir = filt(ir, butter("highpass", 120))
    ir[: int(0.004 * SR)] *= np.linspace(0, 1, int(0.004 * SR))[:, None]
    ir = np.vstack([np.zeros((int(predelay * SR), 2)), ir])
    return ir / np.sqrt((ir ** 2).sum(axis=0, keepdims=True))


def convolve_st(x: np.ndarray, ir: np.ndarray) -> np.ndarray:
    """mono or stereo in -> stereo out, same length as x."""
    if x.ndim == 1:
        x = np.stack([x, x], axis=1)
    out = np.stack([signal.fftconvolve(x[:, c], ir[:, c])[: len(x)] for c in range(2)], axis=1)
    return out


def band_noise(n: int, centre: np.ndarray, width_oct: np.ndarray, amp: np.ndarray, seed: int) -> np.ndarray:
    """Noise through a moving log-Gaussian band (STFT mask). Arrays are per output sample."""
    rng = np.random.default_rng(seed)
    x = rng.standard_normal(n + 2048)
    f, tt, Z = signal.stft(x, fs=SR, nperseg=1024, noverlap=768)
    idx = np.clip((tt * SR).astype(int), 0, n - 1)
    c = centre[idx]
    w = width_oct[idx]
    a = amp[idx]
    ff = np.maximum(f, 1.0)[:, None]
    mask = np.exp(-0.5 * (np.log2(ff / c[None, :]) / w[None, :]) ** 2) * a[None, :]
    _, y = signal.istft(Z * mask, fs=SR, nperseg=1024, noverlap=768)
    return y[:n]


def soft_clip(x: np.ndarray, drive: float = 1.5) -> np.ndarray:
    return np.tanh(drive * x) / np.tanh(drive)


# --------------------------------------------------------------------------
# Instruments
# --------------------------------------------------------------------------
DETUNE_CENTS = [-19, -12, -6, 0, 6, 12, 19]


def pad_note(midi: float, n: int, seed: int) -> np.ndarray:
    rng = np.random.default_rng(seed)
    out = np.zeros((n, 2))
    for k, c in enumerate(DETUNE_CENTS):
        f = np.full(n, mtof(midi) * 2 ** (c / 1200.0))
        # slow drift for life
        f *= 1 + 0.0009 * np.sin(2 * np.pi * (0.13 + 0.05 * k) * np.arange(n) / SR + rng.uniform(0, 6.28))
        v = polyblep_saw(f, rng.uniform(0, 1))
        pan = -0.85 + 1.7 * k / (len(DETUNE_CENTS) - 1)
        l, r = pan_gains(pan)
        out[:, 0] += v * l
        out[:, 1] += v * r
    return out / len(DETUNE_CENTS)


def pluck(midi: float, dur: float, bright: float = 1.0) -> np.ndarray:
    n = int(dur * SR)
    t = np.arange(n) / SR
    f0 = mtof(midi)
    y = np.zeros(n)
    for k in range(1, 16):
        if f0 * k > 16000:
            break
        decay = 0.55 / (1 + 0.55 * (k - 1) ** 1.25 / bright)
        y += (1.0 / k) * np.sin(2 * np.pi * f0 * k * t + 0.3 * k) * np.exp(-t / decay)
    y *= np.clip(t / 0.002, 0, 1)
    return y * 0.5


def kick(vel: float = 1.0) -> np.ndarray:
    n = int(0.5 * SR)
    t = np.arange(n) / SR
    f = 44 + 120 * np.exp(-t / 0.032)
    body = sine_sweep(f) * np.exp(-t / 0.26) * np.clip(t / 0.0012, 0, 1)
    click = RNG.standard_normal(n) * np.exp(-t / 0.0025)
    click = filt(click, butter("highpass", 1800))
    return soft_clip(body * 0.95 + click * 0.18, 1.6) * vel


def clap(vel: float = 1.0) -> np.ndarray:
    n = int(0.35 * SR)
    t = np.arange(n) / SR
    noise = RNG.standard_normal(n)
    env = np.zeros(n)
    for d in (0.0, 0.009, 0.018):
        env += np.where(t >= d, np.exp(-(t - d) / 0.006), 0)
    env += np.where(t >= 0.024, 0.6 * np.exp(-(t - 0.024) / 0.075), 0)
    y = filt(noise * env, butter("bandpass", [900, 4200]))
    return y * 0.8 * vel


def hat(vel: float = 1.0, open_: bool = False) -> np.ndarray:
    n = int((0.22 if open_ else 0.06) * SR)
    t = np.arange(n) / SR
    y = RNG.standard_normal(n) * np.exp(-t / (0.09 if open_ else 0.016))
    y = filt(y, butter("highpass", 7200))
    return y * 0.55 * vel


def snare(vel: float = 1.0, tone: float = 190.0) -> np.ndarray:
    n = int(0.2 * SR)
    t = np.arange(n) / SR
    body = np.sin(2 * np.pi * tone * t) * np.exp(-t / 0.045)
    sn = filt(RNG.standard_normal(n), butter("bandpass", [1500, 7500])) * np.exp(-t / 0.07)
    return (0.5 * body + 0.9 * sn) * vel


def sub_drop(f_start: float, f_end: float, dur: float, tau: float) -> np.ndarray:
    n = int(dur * SR)
    t = np.arange(n) / SR
    f = f_end + (f_start - f_end) * np.exp(-t / (dur / 3.2))
    y = sine_sweep(f) * np.exp(-t / tau) * np.clip(t / 0.004, 0, 1)
    return soft_clip(y * 1.3, 1.8)


def fm_bell(midi: float, dur: float, ratio: float = 3.5, index: float = 2.6) -> np.ndarray:
    n = int(dur * SR)
    t = np.arange(n) / SR
    fc = mtof(midi)
    mod = np.sin(2 * np.pi * fc * ratio * t) * index * np.exp(-t / 0.55)
    y = np.sin(2 * np.pi * fc * t + mod) * np.exp(-t / 1.9) * np.clip(t / 0.003, 0, 1)
    y += 0.25 * np.sin(2 * np.pi * fc * 2.0 * t) * np.exp(-t / 0.8)
    return y * 0.4


# --------------------------------------------------------------------------
# SFX
# --------------------------------------------------------------------------
def tick(pitch: float = 5200.0) -> np.ndarray:
    n = int(0.05 * SR)
    t = np.arange(n) / SR
    ping = np.sin(2 * np.pi * pitch * t) * np.exp(-t / 0.006)
    nz = filt(RNG.standard_normal(n), butter("bandpass", [2500, 9000])) * np.exp(-t / 0.002)
    return 0.6 * ping + 0.5 * nz


def shimmer(dur: float, base: float = 3800.0, seed: int = 1) -> np.ndarray:
    rng = np.random.default_rng(seed)
    n = int(dur * SR)
    t = np.arange(n) / SR
    y = np.zeros(n)
    for k in range(7):
        f = base * (1 + 0.37 * k + rng.uniform(-0.04, 0.04))
        start = rng.uniform(0, dur * 0.35)
        e = np.where(t >= start, np.exp(-(t - start) / rng.uniform(0.12, 0.35)), 0)
        e *= np.clip((t - start) / 0.004, 0, 1)
        y += np.sin(2 * np.pi * f * t + rng.uniform(0, 6.28)) * e / (1 + 0.25 * k)
    air = filt(rng.standard_normal(n), butter("highpass", 9000)) * np.exp(-t / (dur * 0.4)) * 0.25
    return (y * 0.35 + air) * np.sin(np.pi * np.clip(t / dur, 0, 1)) ** 0.35


def whoosh(dur: float, f_lo: float, f_hi: float, peak: float = 0.55, seed: int = 3, width: float = 0.9) -> np.ndarray:
    n = int(dur * SR)
    x = np.linspace(0, 1, n)
    centre = f_lo * (f_hi / f_lo) ** np.sin(np.pi * np.clip(x / (2 * peak), 0, 0.5)) ** 1.0
    centre = np.where(x <= peak, centre, f_hi * (f_lo * 1.6 / f_hi) ** ((x - peak) / (1 - peak)))
    amp = np.where(x <= peak, (x / peak) ** 2.2, np.exp(-(x - peak) / (1 - peak) * 4.0))
    return band_noise(n, centre, np.full(n, width), amp, seed) * 1.6


def beep(freq: float, dur: float) -> np.ndarray:
    n = int(dur * SR)
    t = np.arange(n) / SR
    e = np.clip(t / 0.003, 0, 1) * np.clip((dur - t) / 0.004, 0, 1)
    return np.sin(2 * np.pi * freq * t) * e


def blip(f0: float = 1400.0, f1: float = 1750.0, dur: float = 0.07) -> np.ndarray:
    """UI blip with two soft echoes (90 / 180 ms) so it reads as a premium UI tone."""
    n = int(dur * SR)
    t = np.arange(n) / SR
    f = f0 + (f1 - f0) * np.clip(t / (dur * 0.5), 0, 1)
    one = sine_sweep(f) * np.clip(t / 0.002, 0, 1) * np.exp(-t / (dur * 0.35)) * 0.6
    d = int(0.09 * SR)
    out = np.zeros(n + 2 * d)
    out[:n] += one
    out[d:d + n] += 0.42 * one
    out[2 * d:2 * d + n] += 0.18 * one
    return out


def draw_sweep(dur: float, f0: float = 1800.0, f1: float = 6800.0, seed: int = 5) -> np.ndarray:
    """Soft airy sweep that lasts exactly as long as a line/bar draws itself."""
    n = int(dur * SR)
    x = np.linspace(0, 1, n)
    centre = f0 * (f1 / f0) ** x
    amp = np.sin(np.pi * np.clip(x, 0, 1)) ** 0.7
    return band_noise(n, centre, np.full(n, 0.5), amp, seed) * 1.4


def blade_click(seed: int, pitch: float) -> np.ndarray:
    rng = np.random.default_rng(seed)
    n = int(0.03 * SR)
    t = np.arange(n) / SR
    tr = filt(rng.standard_normal(n), butter("bandpass", [2600, 8000])) * np.exp(-t / 0.0016)
    res = np.sin(2 * np.pi * pitch * t) * np.exp(-t / 0.007)
    return 0.7 * tr + 0.35 * res


def shutter_curtain(seed: int, brightness: float) -> np.ndarray:
    rng = np.random.default_rng(seed)
    n = int(0.09 * SR)
    t = np.arange(n) / SR
    snap = filt(rng.standard_normal(n), butter("bandpass", [1200, 9000])) * np.exp(-t / 0.004)
    ring = (np.sin(2 * np.pi * 2350 * brightness * t) + 0.6 * np.sin(2 * np.pi * 3710 * brightness * t)) * np.exp(-t / 0.018)
    thump = np.sin(2 * np.pi * 95 * t) * np.exp(-t / 0.02)
    return 0.8 * snap + 0.22 * ring + 0.35 * thump


# --------------------------------------------------------------------------
# Composition
# --------------------------------------------------------------------------
CHORDS = [  # (start s, end s, pad voicing, bass midi, name)
    (0.0, 2.0, [62, 66, 69, 73], 35, "Bm9"),
    (2.0, 4.0, [62, 66, 67, 71], 31, "Gmaj7"),
    (4.0, 6.0, [57, 62, 66, 69], 30, "D/F#"),
    (6.0, 8.0, [62, 66, 67, 71], 28, "Em9"),
    (8.0, 10.0, [62, 66, 67, 71, 74], 31, "Gmaj7"),
    (10.0, 12.0, [61, 64, 69, 73], 33, "A"),
    (12.0, 13.0, [62, 64, 69, 74], 33, "Asus4"),
    (13.0, 15.0, [61, 64, 66, 69, 74], 38, "Dmaj9"),
]


def build_music(cues: dict) -> tuple[np.ndarray, list[float]]:
    music = np.zeros((N, 2))
    t_all = np.arange(N) / SR
    flash_t = tsec(cues["closing"]["flash"])  # 12.4 s: groove stops on the flash
    hit_t = tsec(cues["closing"]["accent"])  # 13.0 s: Dmaj9
    drop_t = tsec(cues["iris"]["wordsOut"][0])  # 8.0 s

    # ---- pad: detuned saws per chord, crossfaded, through a moving low-pass
    pad = np.zeros((N, 2))
    xf = int(0.06 * SR)
    for ci, (a, b, notes, _, _) in enumerate(CHORDS):
        s0, s1 = int(a * SR), int(b * SR)
        tail = int(2.0 * SR) if ci == len(CHORDS) - 1 else xf
        n = min(s1 - s0 + tail, N - s0)
        seg = np.zeros((n, 2))
        for k, m in enumerate(notes):
            seg += pad_note(m, n, seed=100 * ci + k)
        seg /= np.sqrt(len(notes))
        env = np.ones(n)
        env[:xf] = np.linspace(0, 1, xf) if ci else np.linspace(0, 1, xf)
        if ci < len(CHORDS) - 1:
            env[-xf:] *= np.linspace(1, 0, xf)
        place_st(pad, seg * env[:, None], s0)
    # cutoff automation (Hz): intro opens, breakdown darkens, drop opens, final warm
    keys = [(0, 500), (1.5, 1600), (2.0, 2400), (6.0, 2200), (6.6, 520), (7.6, 900), (8.0, 4200),
            (12.3, 3400), (12.4, 1800), (13.0, 3200), (15.0, 900)]
    cutoff = np.interp(t_all, [k[0] for k in keys], [k[1] for k in keys])
    pad = tv_lowpass(pad, cutoff)
    pad_gain = np.interp(t_all, [0, 1.2, 6.0, 6.4, 8.0, 12.4, 12.45, 13.0, 15.0],
                         [0.0, 0.85, 0.85, 0.7, 0.9, 0.9, 0.5, 1.0, 1.0])
    pad *= pad_gain[:, None] * 0.55

    # ---- final chord swell: reverse reverb into the hit
    hit_s = int(hit_t * SR)

    # ---- sub + bass: 8ths in the groove, long notes in intro/breakdown
    bass = np.zeros((N, 2))
    kick_times: list[float] = []
    for ci, (a, b, _, root, name) in enumerate(CHORDS):
        if name == "Dmaj9":
            continue
        groove = name not in ("Bm9", "Em9")
        if groove:
            steps = np.arange(a, b, BEAT / 2)
            for st in steps:
                if st >= flash_t:
                    break
                d = BEAT / 2 * 0.92
                n = int(d * SR)
                t = np.arange(n) / SR
                f = mtof(root)
                e = np.clip(t / 0.004, 0, 1) * np.exp(-t / 0.16)
                sub = np.sin(2 * np.pi * f * t) * e
                mid = filt(polyblep_saw(np.full(n, f * 2)), butter("lowpass", 420)) * e * 0.45
                place(bass, sub * 0.55 + mid, int(st * SR))
        else:
            n = int((b - a) * SR)
            t = np.arange(n) / SR
            f = mtof(root)
            e = np.clip(t / 0.3, 0, 1) * np.clip((b - a - t) / 0.08, 0, 1)
            sub = np.sin(2 * np.pi * f * t) * e
            mid = filt(polyblep_saw(np.full(n, f * 2)), butter("lowpass", 300)) * e * 0.35
            g = 0.18 if name == "Bm9" else 0.7
            place(bass, (sub * 0.8 + mid) * g, int(a * SR))
    # final: D bass under the Dmaj9 hit
    n = N - hit_s
    t = np.arange(n) / SR
    e = np.clip(t / 0.01, 0, 1) * np.exp(-t / 1.1)
    place(bass, (np.sin(2 * np.pi * mtof(38) * t) * 0.8 + filt(polyblep_saw(np.full(n, mtof(50))), butter("lowpass", 380)) * 0.3) * e, hit_s)

    # ---- pluck arpeggio with ping-pong delay
    arp = np.zeros((N, 2))
    pattern = [0, 1, 2, 3, 4, 3, 2, 1]
    for ci, (a, b, notes, _, name) in enumerate(CHORDS):
        if name in ("Em9", "Dmaj9"):
            continue
        tones = sorted(notes) + [sorted(notes)[1] + 12]
        step = BEAT / 4 if name not in ("Bm9",) else BEAT / 2
        start = a + (1.0 if name == "Bm9" else 0.0)
        octave = 12 if name in ("Gmaj7", "A", "Asus4") and a >= 8.0 else 0
        for i, st in enumerate(np.arange(start, b, step)):
            if st >= flash_t:
                break
            m = tones[pattern[i % len(pattern)] % len(tones)] + octave
            vel = 0.75 + 0.25 * ((i % 4) == 0)
            y = pluck(m, 0.45, bright=1.4 if a >= 8.0 else 1.0) * vel
            place(arp, y, int(st * SR), pan=(-0.35 if i % 2 else 0.35))
    delay = int(0.375 * SR)  # dotted eighth
    pp = np.zeros_like(arp)
    mono = arp.sum(axis=1) * 0.5
    for k in range(1, 6):
        g = 0.42 ** k
        ch = k % 2  # alternate L/R
        pp[k * delay:, ch] += mono[: N - k * delay] * g
    arp = arp + filt(pp, butter("lowpass", 5200))
    arp_gain = np.interp(t_all, [0, 1.0, 2.0, 6.0, 6.05, 8.0, 8.02, 12.4, 12.45], [0, 0.35, 0.6, 0.6, 0.0, 0.0, 0.7, 0.7, 0.0])
    arp *= arp_gain[:, None] * 0.5

    # ---- drums (bars 2-3, 5-7 until the flash)
    drums = np.zeros((N, 2))
    groove_bars = [(2.0, 6.0), (8.0, flash_t)]
    for a, b in groove_bars:
        for st in np.arange(a, b - 1e-6, BEAT):
            kick_times.append(st)
            place(drums, kick(1.0 if abs(st - drop_t) > 1e-6 else 1.25), int(st * SR), gain=0.66)
            beat_in_bar = int(round((st % BAR) / BEAT))
            if beat_in_bar in (1, 3):
                place(drums, clap(), int(st * SR), pan=0.05, gain=0.55)
        for i, st in enumerate(np.arange(a, b - 1e-6, BEAT / 4)):
            off = i % 4 == 2  # off-beat eighth
            if a >= 8.0:
                v = 0.8 if off else (0.34 if i % 2 else 0.22)  # drop: full sixteenths
            elif off or i % 2 == 1:
                v = 0.7 if off else 0.2  # groove: off-beats + ghost sixteenths
            else:
                continue
            place(drums, hat(v, open_=(off and i % 16 == 14)), int(st * SR), pan=0.22 if i % 2 else -0.18, gain=0.5)
    # snare roll into the drop: 16ths -> 32nds -> 64ths, crescendo, pitch rising
    roll_t = []
    t = 7.25
    while t < drop_t - 0.005:
        roll_t.append(t)
        t += BEAT / 4 if t < 7.5 - 1e-9 else (BEAT / 8 if t < 7.875 - 1e-9 else BEAT / 16)
    for i, st in enumerate(roll_t):
        v = 0.25 + 0.75 * (i / max(1, len(roll_t) - 1)) ** 1.6
        place(drums, snare(v, tone=180 + 90 * i / len(roll_t)), int(st * SR), pan=0.0, gain=0.6)
    # riser through the breakdown
    rs, re_ = 6.4, drop_t
    n = int((re_ - rs) * SR)
    x = np.linspace(0, 1, n)
    riser = band_noise(n, 400 * (9000 / 400) ** x, np.full(n, 0.6), x ** 2.4, seed=77)
    riser += 0.18 * polyblep_saw(110 * 2 ** (2.0 * x)) * x ** 3
    place(drums, filt(riser, butter("highpass", 200)), int(rs * SR), gain=0.5)
    # drop: sub drop + soft impact
    place(drums, sub_drop(78, 30, 1.6, 0.55), int(drop_t * SR), gain=0.7)
    imp = band_noise(int(0.8 * SR), np.full(int(0.8 * SR), 900.0), np.full(int(0.8 * SR), 1.8),
                     np.exp(-np.arange(int(0.8 * SR)) / SR / 0.18), seed=88)
    place_st(drums, convolve_st(imp, reverb_ir(1.6, 0.45)) * 0.35, int(drop_t * SR))

    # ---- sidechain: pad, bass, arp pump under each kick
    sc = np.zeros(N)
    for kt in kick_times:
        s = int(kt * SR)
        n = min(int(0.3 * SR), N - s)
        tt_ = np.arange(n) / SR
        sc[s:s + n] = np.maximum(sc[s:s + n], np.clip(tt_ / 0.003, 0, 1) * np.exp(-tt_ / 0.11))
    pump = 1.0 - 0.5 * sc
    pad *= pump[:, None]
    bass *= (1.0 - 0.65 * sc)[:, None]
    arp *= (1.0 - 0.35 * sc)[:, None]

    # ---- final hit: Dmaj9 FM bells + swell (reverse reverb) into 13.0 s
    bells = np.zeros((N, 2))
    for k, m in enumerate([74, 78, 81, 85, 88]):
        place(bells, fm_bell(m, 2.0), hit_s + int(k * 0.028 * SR), pan=-0.5 + 0.25 * k, gain=0.55)
    swell_len = hit_s - int(flash_t * SR)
    src = np.zeros(int(2.4 * SR))
    for m in [62, 66, 69, 73, 76]:
        src[: int(0.4 * SR)] += pluck(m, 0.4, bright=1.6)
    wet = convolve_st(src, reverb_ir(2.4, 0.7))
    rev = wet[::-1][-swell_len:] if len(wet) >= swell_len else wet[::-1]
    rev = rev * (np.linspace(0, 1, len(rev)) ** 2.2)[:, None]
    rev /= np.max(np.abs(rev)) + 1e-9
    place_st(bells, rev * 0.9, hit_s - len(rev))
    # reversed airy noise swell (reverse cymbal) rising into the hit
    nn = swell_len
    xs = np.linspace(0, 1, nn)
    air = band_noise(nn, 2500 * (7000 / 2500) ** xs, np.full(nn, 1.2), xs ** 3.2, seed=91)
    place(bells, air * 0.9, hit_s - nn, pan=0.0)

    # ---- buses + reverb
    hall = reverb_ir(3.2, 0.9)
    music = pad + bass + arp + drums + bells
    send = pad * 0.25 + arp * 0.35 + bells * 0.6 + drums * 0.08
    music += convolve_st(send, hall) * 0.55
    return music, kick_times


def build_sfx(cues: dict) -> tuple[np.ndarray, list[tuple]]:
    sfx = np.zeros((N, 2))
    ev: list[tuple] = []  # (name, frame[, frame where its loudness is measured])
    O, Kc, I, P, Cl = cues["opening"], cues["kit"], cues["iris"], cues["pro"], cues["closing"]

    # opening: a tick per SONY letter (panned S -> Y), then the glint along the shine
    for i, f in enumerate(O["letters"]):
        place(sfx, tick(4700 + 260 * i), fs(f), pan=-0.45 + 0.3 * i, gain=1.0)
        ev.append((f"tick letra {'SONY'[i]}", f))
    sh_n = int(tsec(O["shine"]["dur"] + 8) * SR)
    place(sfx, shimmer(sh_n / SR, 3900, seed=11), fs(O["shine"]["start"]), pan=np.linspace(-0.6, 0.6, sh_n), gain=0.5)
    ev.append(("brillo SONY", O["shine"]["start"]))

    # whip-pan: one whoosh, right -> left, peaking mid-pan (also carries the α6400 in)
    w0, wd = O["exit"][0], Kc["whipIn"]["dur"] + 4
    n = int(tsec(wd) * SR)
    place(sfx, whoosh(n / SR, 260, 5200, peak=0.5, seed=21), fs(w0 - 1), pan=np.linspace(0.8, -0.8, n), gain=0.9)
    ev.append(("whoosh barrido a la α6400", w0, w0 + 2))

    # AF confirm: double 3150 Hz beep when the kit snaps into focus
    for k in range(2):
        place(sfx, beep(3150, 0.045), fs(Kc["focusSnap"]) + int(k * 0.085 * SR), gain=0.32)
    ev.append(("bip AF (doble 3150 Hz)", Kc["focusSnap"]))
    place(sfx, blip(1250, 1500), fs(Kc["bar"]["start"]), gain=0.8)
    ev.append(("blip barra 1/2", Kc["bar"]["start"]))

    # push into the lens: a long accelerating whoosh
    pd = Kc["push"]["dur"] + 4
    n = int(tsec(pd) * SR)
    place(sfx, whoosh(n / SR, 140, 3400, peak=0.82, seed=31, width=1.1), fs(Kc["push"]["start"]), gain=1.3)
    ev.append(("whoosh empuje al lente", Kc["push"]["start"], Kc["push"]["start"] + 25))

    # iris: clicks spread over the exact closing / opening animation
    def clicks(start: float, dur: float, count: int, seed: int, base: float, label: str, gain: float = 0.62):
        # denser where the blades move fastest (inOut curve -> middle)
        u = (np.arange(count) + 0.5) / count
        ts = start + dur * (0.5 - np.cos(np.pi * u) / 2)
        for k, tf in enumerate(ts):
            place(sfx, blade_click(seed + k, base * (1 + 0.03 * ((k * 7) % 5))), fs(tf), pan=0.25 * np.sin(k * 1.7), gain=gain)
        ev.append((label, start))

    clicks(I["close"]["start"], I["close"]["dur"], 14, 300, 2100, "clicks diafragma cerrando (7 hojas)")
    clicks(I["reopen"]["start"], I["reopen"]["dur"], 22, 400, 2450, "clicks diafragma abriendo (11 hojas)", gain=0.8)
    # focal-plane shutter: two curtains
    sh0 = I["shutter"]["start"]
    place(sfx, shutter_curtain(51, 1.0), fs(sh0 + 0.5), gain=0.75)
    place(sfx, shutter_curtain(52, 1.12), fs(sh0 + 0.5) + int(0.062 * SR), gain=0.62)
    ev.append(("obturador plano focal (2 cortinas)", sh0))

    # drop: words shoot up + a7 V rises
    n = int(0.55 * SR)
    place(sfx, whoosh(0.55, 500, 7000, peak=0.35, seed=41), fs(I["wordsOut"][0]), gain=0.7)
    ev.append(("whoosh salto (palabras arriba)", I["wordsOut"][0]))
    n = int(tsec(P["camIn"]["dur"] + 6) * SR)
    place(sfx, whoosh(n / SR, 180, 2600, peak=0.45, seed=42), fs(P["camIn"]["start"] + 1), gain=0.6)
    ev.append(("whoosh producto que sube (a7 V)", P["camIn"]["start"], P["camIn"]["start"] + 4))

    # every line / bar that draws itself gets a soft sweep of the same duration
    for label, f0, dur_f, pan, sd in [
        ("barra 1/2 (llenado)", Kc["bar"]["start"], Kc["bar"]["dur"], 0.0, 61),
        ("línea callout 33 MP", P["callout1"]["line"], P["callout1"]["lineDur"], -0.4, 62),
        ("línea a G MASTER", P["seal"]["line"], P["seal"]["lineDur"], 0.2, 63),
        ("línea callout 695 g", P["callout2"]["line"], P["callout2"]["lineDur"], 0.4, 64),
        ("barra 2/2 (llenado)", P["bar"]["start"], P["bar"]["dur"], 0.0, 65),
    ]:
        place(sfx, draw_sweep(tsec(dur_f), seed=sd), fs(f0), pan=pan, gain=0.55)

    # callouts and UI
    place(sfx, blip(1500, 1900), fs(P["callout1"]["dot"]), gain=0.85)
    ev.append(("blip callout 33 MP (punto)", P["callout1"]["dot"]))
    place(sfx, blip(1900, 2300, 0.06), fs(P["callout1"]["label"]), pan=-0.35, gain=0.55)
    ev.append(("blip callout 33 MP (cifra)", P["callout1"]["label"]))
    n = int(tsec(P["lensIn"]["dur"] + 6) * SR)
    place(sfx, whoosh(n / SR, 220, 3000, peak=0.4, seed=43), fs(P["lensIn"]["start"]), pan=np.linspace(-0.8, -0.2, n), gain=0.6)
    ev.append(("whoosh entra el 24-70 GM II", P["lensIn"]["start"], P["lensIn"]["start"] + 3))
    place(sfx, blip(1300, 1450, 0.07), fs(P["seal"]["line"]), pan=-0.1, gain=0.8)
    ev.append(("blip línea a G MASTER", P["seal"]["line"]))
    gl_n = int(0.7 * SR)
    place(sfx, shimmer(0.7, 4600, seed=12), fs(P["seal"]["glint"]), pan=np.linspace(0.1, 0.7, gl_n), gain=0.5)
    ev.append(("brillo sello G MASTER", P["seal"]["glint"]))
    place(sfx, blip(1500, 1900), fs(P["callout2"]["dot"]), pan=-0.3, gain=0.7)
    ev.append(("blip callout 695 g (punto)", P["callout2"]["dot"]))
    place(sfx, blip(1900, 2300, 0.06), fs(P["callout2"]["label"]), pan=0.35, gain=0.55)
    ev.append(("blip callout 695 g (cifra)", P["callout2"]["label"]))
    place(sfx, blip(1250, 1700), fs(P["bar"]["start"]), gain=0.65)
    ev.append(("blip barra 2/2", P["bar"]["start"]))

    # camera flash at 372: charging whine -> pop + thump
    fl = Cl["flash"]
    wn = int(0.55 * SR)
    t = np.arange(wn) / SR
    f = 1800 * (8800 / 1800) ** (t / t[-1]) ** 1.4
    whine = sine_sweep(f) * (t / t[-1]) ** 2.5 * 0.18
    whine += 0.05 * sine_sweep(f * 2.01) * (t / t[-1]) ** 3
    place(sfx, whine, fs(fl) - wn, gain=0.8)
    pn = int(0.12 * SR)
    t = np.arange(pn) / SR
    pop = filt(RNG.standard_normal(pn), butter("bandpass", [900, 12000])) * np.exp(-t / 0.0045)
    pop += 0.4 * np.sin(2 * np.pi * 1650 * t) * np.exp(-t / 0.01)
    place(sfx, pop, fs(fl), gain=0.9)
    th = np.sin(2 * np.pi * (55 + 40 * np.exp(-t / 0.02)) * t) * np.exp(-t / 0.07)
    place(sfx, np.concatenate([th, np.zeros(int(0.1 * SR))]), fs(fl), gain=0.8)
    place_st(sfx, convolve_st(pop * 0.6, reverb_ir(1.2, 0.3)) * 0.25, fs(fl))
    ev.append(("flash (silbido + pop + thump)", fl))

    # final hit at 390: impact + sub drop (bells/swell live in the music)
    hit = Cl["accent"]
    n = int(1.4 * SR)
    t = np.arange(n) / SR
    boom = sine_sweep(40 + 70 * np.exp(-t / 0.05)) * np.exp(-t / 0.5)
    crack = filt(RNG.standard_normal(n), butter("bandpass", [200, 5000])) * np.exp(-t / 0.03)
    impact = soft_clip(boom * 0.9 + crack * 0.35, 1.4)
    place_st(sfx, convolve_st(impact, reverb_ir(2.0, 0.55)) * 0.3, fs(hit))
    place(sfx, impact, fs(hit), gain=0.75)
    place(sfx, sub_drop(66, 27, 1.9, 0.7), fs(hit), gain=0.7)
    ev.append(("golpe final + sub drop", hit))
    return sfx, ev


def follower(x: np.ndarray, attack_s: float, release_s: float) -> np.ndarray:
    """Peak envelope follower with separate attack and release."""
    ga = np.exp(-1.0 / (attack_s * SR))
    gr = np.exp(-1.0 / (release_s * SR))
    out = np.empty_like(x)
    cur = 0.0
    for i, v in enumerate(x):
        g = ga if v > cur else gr
        cur = v + (cur - v) * g
        out[i] = cur
    return out


def duck_music(music: np.ndarray, sfx: np.ndarray, depth_db: float = -7.0) -> tuple[np.ndarray, np.ndarray]:
    """Automatic ducking: music goes down 7 dB while an effect is sounding."""
    a = maximum_filter1d(np.max(np.abs(sfx), axis=1), size=int(0.01 * SR))
    lead = int(0.008 * SR)
    a = np.concatenate([a[lead:], np.zeros(lead)])  # duck 8 ms before the effect
    amount = np.clip(follower(np.clip(a / 0.045, 0, 1), 0.005, 0.18), 0, 1)
    gain = 10 ** (depth_db * amount / 20)
    return music * gain[:, None], gain


def limiter_gain(x: np.ndarray, ceiling_db: float, lookahead_ms: float = 2.0, release_ms: float = 90.0) -> np.ndarray:
    """Look-ahead true-peak limiter gain curve (offline, no added delay)."""
    ceiling = 10 ** (ceiling_db / 20)
    up = np.abs(signal.resample_poly(x, 4, 1, axis=0)).max(axis=1)
    peak = up[: 4 * len(x)].reshape(-1, 4).max(axis=1)
    need = np.minimum(1.0, ceiling / np.maximum(peak, 1e-9))
    la = int(lookahead_ms * 1e-3 * SR)
    # forward-looking minimum: the gain is already down when the peak arrives
    win_min = minimum_filter1d(need, size=2 * la + 1, mode="nearest")
    # exponential release
    g = np.empty_like(win_min)
    rel = np.exp(-1.0 / (release_ms * 1e-3 * SR))
    cur = 1.0
    for i, target in enumerate(win_min):
        cur = target if target < cur else target + (cur - target) * rel
        g[i] = cur
    # raised-cosine smoothing of the attack, never above what each sample needs
    k = np.hanning(2 * la + 1)
    k /= k.sum()
    gs = np.convolve(np.concatenate([np.full(la, g[0]), g, np.full(la, g[-1])]), k, mode="valid")
    return np.minimum(gs, need)


def main(project: str) -> None:
    proj = Path(project)
    cues = json.loads((proj / "src/timeline/cues.json").read_text())
    assert cues["fps"] == FPS and cues["durationInFrames"] == DUR_FRAMES

    music, _ = build_music(cues)
    sfx, events = build_sfx(cues)
    dc = butter("highpass", 18.0)
    music, sfx = filt(music, dc), filt(sfx, dc)

    # level the beds before ducking: music under the effects
    music *= 10 ** ((-23.0 - integrated_lufs(music)) / 20)
    sfx *= 10 ** ((-19.5 - integrated_lufs(sfx)) / 20)
    music_d, duck_gain = duck_music(music, sfx, -7.0)

    # clean ending: the tail decays naturally, a final raised-cosine guarantees silence
    t = np.arange(N) / SR
    fade = np.where(t > 14.35, np.cos(np.clip((t - 14.35) / 0.63, 0, 1) * np.pi / 2) ** 2, 1.0)
    music_d *= fade[:, None]
    sfx *= fade[:, None]

    # master: gain to -14 LUFS, true-peak limiter at -1.2 dBTP (iterate: limiting costs loudness)
    mix = music_d + sfx
    gain = 10 ** ((TARGET_LUFS - integrated_lufs(mix)) / 20)
    for _ in range(8):
        g_lim = limiter_gain(mix * gain, CEILING_DBTP - 0.5)  # 0.5 dB headroom for AAC overshoot
        out = mix * gain * g_lim[:, None]
        err = TARGET_LUFS - integrated_lufs(out)
        if abs(err) < 0.02:
            break
        gain *= 10 ** (err / 20)
    master_curve = gain * g_lim
    mix_out = mix * master_curve[:, None]
    music_out = music_d * master_curve[:, None]
    sfx_out = sfx * master_curve[:, None]

    # 16-bit with TPDF dither (stems differ from the mix only by dither LSBs)
    def to16(x: np.ndarray, seed: int) -> np.ndarray:
        rng = np.random.default_rng(seed)
        d = (rng.random(x.shape) - rng.random(x.shape)) / 32768.0
        return np.clip(np.round((x + d) * 32767.0), -32768, 32767).astype(np.int16)

    out_dir = proj / "public/audio"
    out_dir.mkdir(parents=True, exist_ok=True)
    mix16, mus16, sfx16 = to16(mix_out, 1), to16(music_out, 2), to16(sfx_out, 3)
    # exact digital silence for the last 20 ms
    for a in (mix16, mus16, sfx16):
        a[-int(0.02 * SR):] = 0
    wavfile.write(out_dir / "sony-scala-mix.wav", SR, mix16)
    wavfile.write(out_dir / "music.wav", SR, mus16)
    wavfile.write(out_dir / "sfx.wav", SR, sfx16)

    # ---------------- report
    m = mix16.astype(float) / 32768.0
    mu = mus16.astype(float) / 32768.0
    sf = sfx16.astype(float) / 32768.0
    lufs = integrated_lufs(m)
    tp = true_peak_dbtp(m)
    tail = db(np.max(np.abs(m[-int(0.02 * SR):])) + 1e-12)
    rows = []
    for e in sorted(events, key=lambda e: e[1]):
        name, f = e[0], e[1]
        s = fs(e[2] if len(e) > 2 else f)
        gm = 20 * np.log10(duck_gain[min(s + int(0.05 * SR), N - 1)])
        rows.append((f, name, momentary_lufs(mu, s), momentary_lufs(sf, s), momentary_lufs(m, s), gm))
    lines = [
        "# Loudness report — sony-scala-mix.wav",
        "",
        f"- Duración: {len(m) / SR:.3f} s ({len(m)} muestras, {SR} Hz, estéreo, 16-bit)",
        f"- Integrado (BS.1770-4, K-weighting, gate −70 LUFS absoluto + −10 LU relativo): **{lufs:.2f} LUFS**",
        f"- True peak (4× oversampling): **{tp:.2f} dBTP**",
        f"- Últimos 20 ms: pico {tail:.1f} dBFS",
        "",
        "Momentary loudness (ventana de 400 ms desde el evento; en los whooshes, cerca de su pico).",
        "La música queda por debajo de los efectos; *ducking* = ganancia aplicada a la música 50 ms después.",
        "",
        "| frame | t (s) | evento | música | sfx | mezcla | ducking |",
        "|---:|---:|---|---:|---:|---:|---:|",
    ]
    for f, name, lm, ls, lx, gm in rows:
        lines.append(f"| {f:g} | {f / FPS:.2f} | {name} | {lm:.1f} | {ls:.1f} | {lx:.1f} | {gm:.1f} dB |")
    (proj / "audio-src/loudness-report.md").write_text("\n".join(lines) + "\n")
    print("\n".join(lines))


if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else ".")
